    public abstract void calculateMove(Player player);

    public List<Group> findGroups(Referee ref, PlayerColor color) {
      List<Group> groups = new ArrayList<Group>(Player.FIELDS_ON_BOARD / 2);
      Set<FieldPosition> known = new HashSet<>();
      for (int row = 0; row < Player.BOARD_SIZE; row++) {
        for (int col = 0; col < Player.BOARD_SIZE; col++) {
          FieldPosition pos = new FieldPosition(row, col);
          if (!known.contains(pos) && ref.getStoneColor(pos) == color) {
            Group group = Group.findGroup(ref, pos);
            groups.add(group);
            known.addAll(group.getStones());
          }
        }
      }

      return groups;
    }

    protected void update() {
      // update current scores
      referee.getGame().setStonesCaptured(Player.MY_COLOR, Player.MY_SCORE);
      referee
          .getGame()
          .setStonesCaptured(PlayerColor.getOpposizeColor(Player.MY_COLOR), Player.OPPONENT_SCORE);
      // update the board
      referee.addMove(Player.OPPONENTS_LAST_MOVE);
      referee.setBoard(Player.BOARD);
      referee.setBoard(referee.getBoardCopy());
    }

    protected Move getRandomMove() {
      Move random;
      do {
        random =
            new Move(
                (int) (Math.random() * Player.BOARD_SIZE - 6 + 3),
                (int) (Math.random() * Player.BOARD_SIZE - 6 + 3),
                Player.MY_COLOR);
      } while (!referee.isValidMove(random));
      return random;
    }

    protected List<FieldPosition> getStonesOnBoard() {
      List<FieldPosition> stones = new ArrayList<FieldPosition>(Player.FIELDS_ON_BOARD);
      PlayerColor[][] board = referee.getBoard();
      for (int i = 0; i < Player.BOARD_SIZE; i++) {
        for (int j = 0; j < Player.BOARD_SIZE; j++) {
          if (board[i][j] != null) {
            stones.add(new FieldPosition(i, j));
          }
        }
      }
      return stones;
    }

    protected List<FieldPosition> getFreeFieldsNear(List<FieldPosition> placedStones) {
      List<FieldPosition> freeFieldsNear = new ArrayList<>(Player.FIELDS_ON_BOARD);
      for (FieldPosition stone : placedStones) {
        for (FieldPosition pos : stone.getFieldsNear()) {
          if (referee.isFieldEmpty(pos)) {
            freeFieldsNear.add(pos);
          }
        }
      }
      return freeFieldsNear;
    }
  }

  public static class Vector2D implements Cloneable {

    public double x;
